import gurobipy as gp
from gurobipy import GRB
records = [r for r in LEGACY_RECORDS if r['source'] == '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/Others_example/Others4/cost.csv']
foods = []
calories = {}
protein = {}
fat = {}
vitaminc = {}
cost = {}
for rec in records:
    v = rec['values']
    food = v['Food']
    foods.append(food)
    try:
        calories[food] = float(v['Calories'])
        protein[food] = float(v['Protein(g)'])
        fat[food] = float(v['Fat(g)'])
        vitaminc[food] = float(v['VitaminC(mg)'])
        cost[food] = float(v['Cost'])
    except Exception as e:
        raise ValueError(f'Missing or invalid data for food {food}: {e}')
for food in foods:
    for (d, name) in [(calories, 'Calories'), (protein, 'Protein(g)'), (fat, 'Fat(g)'), (vitaminc, 'VitaminC(mg)'), (cost, 'Cost')]:
        if food not in d:
            raise ValueError(f'Missing {name} for food {food}')
m = gp.Model('meal_plan')
x_vars = m.addVars(foods, lb=0, vtype=GRB.CONTINUOUS, name='')
m.setObjective(gp.quicksum((cost[f] * x_vars[f] for f in foods)), GRB.MINIMIZE)
m.addConstr(gp.quicksum((calories[f] * x_vars[f] for f in foods)) >= 2000, name='calories')
m.addConstr(gp.quicksum((protein[f] * x_vars[f] for f in foods)) >= 50, name='protein')
m.addConstr(gp.quicksum((vitaminc[f] * x_vars[f] for f in foods)) >= 60, name='vitaminc')
m.addConstr(gp.quicksum((fat[f] * x_vars[f] for f in foods)) <= 70, name='fat')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v in m.getVars():
        print(f'{v.VarName}: {v.X}')
else:
    print(f'Solver status: {m.Status}')